/** Búsqueda insensible por nombre, cargo, país o ciudad. */
export function buscarPersonas(q: string): PersonaAtlas[] {
  const n = q.trim().toLowerCase();
  if (!n) return PERSONAS_ATLAS;
  return PERSONAS_ATLAS.filter(
    (p) => p.nombre.toLowerCase().includes(n) || p.cargo.toLowerCase().includes(n) || p.ciudad.toLowerCase().includes(n) || p.sede.toLowerCase().includes(n)
  );
}

/** Búsqueda de países por nombre, capital o dato. */
export function buscarPaises(q: string): PaisAtlas[] {
  const n = q.trim().toLowerCase();
  if (!n) return PAISES_ATLAS;
  return PAISES_ATLAS.filter(
    (p) => p.nombre.toLowerCase().includes(n) || p.capital.toLowerCase().includes(n) || p.lider.toLowerCase().includes(n) || p.region.toLowerCase().includes(n)
  );
}

/** Formatea superficie/población bonito. */
export function fmtKm2(n: number): string {
  return n.toLocaleString("es-ES") + " km²";
}
export function fmtMillones(n: number): string {
  return n >= 1000 ? `${(n / 1000).toFixed(2).replace(".", ",")} mil millones` : `${String(n).replace(".", ",")} millones`;
}
